+export async function migratePlanSchema(
+	input: {
+		runId: string;
+		commit: string;
+		mode: string;
+		dryRun?: boolean;
+		confirmExclusions?: string;
+	},
+	ctx: ReviewBudgetCommandContext,
+): Promise<
+	Omit<PlanSchemaMigrationView, "migration"> & {
+		migration?: Omit<PlanSchemaMigrationPayload, "authorizedPlanBytes">;
+	}
