+	if (input.mode !== "equivalent" && input.mode !== "selective") {
+		throw new CliError(
+			"INVALID_ARGS",
+			"--mode must be equivalent or selective.",
+		);
+	}
+	if (!/^[0-9a-f]{40}$/u.test(input.commit)) {
+		throw new CliError("INVALID_ARGS", "--commit must be a full sha.");
+	}
