+		throw new CliError(
+			"PLAN_MIGRATION_CONFLICT",
+			"The mapped worktree plan is missing. Refusing to treat that as an empty file.",
+		);
+	}
+	return {
+		bytes: readFileSync(execution.effectivePlanPath, "utf8"),
+		require: true,
+	};
